1	/**
2	 * @module use-mobile
3	 *
4	 * Hooks de detecção de dispositivo com histerese na faixa tablet.
5	 *
6	 * Modos suportados:
7	 * - `mobile`  → viewport &lt; 768px **OU** 768-1279px com aspect-ratio ≤ 10/11
8	 *               (tablets em retrato seguem layout mobile por escolha de produto)
9	 * - `tablet`  → viewport 768-1279px com aspect-ratio ≥ 11/10 (iPad, Surface deitado)
10	 *               **Zona morta** (10/11 &lt; ratio &lt; 11/10, aprox. quadrado): mantém o
11	 *               modo anterior (histerese) em vez de oscilar entre landscape/portrait.
12	 *               Isso elimina o flicker em tablets Android onde o viewport oscila
13	 *               quando a barra de URL aparece/some (dvh instability).
14	 * - `desktop` → viewport ≥ 1280px (qualquer orientação)
15	 *
16	 * Thresholds de aspect-ratio:
17	 * - "claramente paisagem" = ratio ≥ 11/10 (1.10) → tablet
18	 * - "claramente retrato"  = ratio ≤ 10/11 (0.909) → mobile
19	 * - "zona morta"          = 0.909 &lt; ratio &lt; 1.10 → sticky (prevMode ?? 'mobile')
20	 *
21	 * Verificação com os viewports dos testes:
22	 * - 1180×810 → 1.456 ≥ 1.10 → tablet ✓
23	 * - 810×1180 → 0.686 ≤ 0.909 → mobile ✓
24	 * - 1024×768 → 1.333 ≥ 1.10 → tablet ✓
25	 * - 768×1024 → 0.750 ≤ 0.909 → mobile ✓
26	 */
27	
28	import * as React from 'react';
29	import { wideWarn } from '@/shared/lib/telemetry/wide-events';
30	
31	/** Viewport máximo (exclusivo) considerado mobile sem condicionar orientação. */
32	const MOBILE_BREAKPOINT = 768;
33	/** Viewport máximo (exclusivo) da faixa tablet; daí em diante é desktop. */
34	const TABLET_BREAKPOINT = 1280;
35	
36	export type DeviceMode = 'mobile' | 'tablet' | 'desktop';
37	
38	/**
39	 * Classificação pura do modo de dispositivo a partir de dimensões numéricas e
40	 * do estado anterior (para histerese). Não acessa `window` — testável sem DOM.
41	 *
42	 * Exportada para testes unitários diretos da lógica de histerese.
43	 */
44	export function deviceModeFor(
45	  width: number,
46	  height: number,
47	  prev?: DeviceMode,
48	): DeviceMode {
49	  if (width < MOBILE_BREAKPOINT) return 'mobile';
50	  if (width >= TABLET_BREAKPOINT) return 'desktop';
51	
52	  // Faixa 768–1279: decidir por aspect-ratio com zona morta.
53	  const ratio = height > 0 ? width / height : 1;
54	
55	  // Claramente paisagem → tablet
56	  if (ratio >= 11 / 10) return 'tablet';
57	  // Claramente retrato → mobile
58	  if (ratio <= 10 / 11) return 'mobile';
59	  // Zona morta (quase-quadrado): manter estado anterior (histerese).
60	  if (prev === 'tablet' || prev === 'mobile') return prev;
61	  return 'mobile'; // primeira leitura sem histórico: default mobile
62	}
63	
64	/**
65	 * Lê o modo atual usando `matchMedia.matches` (confiável durante orientationchange,
66	 * onde `window.innerWidth/Height` pode refletir a orientação anterior por ~100ms)
67	 * e aplica histerese via `deviceModeFor`.
68	 *
69	 * @param prevMode - Modo anterior; usado pela zona morta de histerese.
70	 */
71	function readDeviceMode(prevMode?: DeviceMode): DeviceMode {
72	  if (typeof window === 'undefined') return 'desktop';
73	
74	  if (window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`).matches) {
75	    return 'mobile';
76	  }
77	  if (window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`).matches) {
78	    return 'desktop';
79	  }
80	
81	  // Faixa 768–1279: aspect-ratio com histerese.
82	  if (window.matchMedia('(min-aspect-ratio: 11/10)').matches) return 'tablet';
83	  if (window.matchMedia('(max-aspect-ratio: 10/11)').matches) return 'mobile';
84	
85	  // Zona morta: sticky.
86	  if (prevMode === 'tablet' || prevMode === 'mobile') return prevMode;
87	  return 'mobile';
88	}
89	
90	/**
91	 * Retorna o modo de dispositivo atual: `mobile`, `tablet` ou `desktop`.
92	 * Reage a mudanças de viewport e orientação.
93	 *
94	 * Debounce de 150ms coalesce rajadas de `resize`/`orientationchange` em um único
95	 * setState, eliminando a dupla atualização que causava flicker em tablets Android.
96	 * A guarda de igualdade (`prev === next ? prev : next`) evita re-renders quando o
97	 * modo não muda de fato.
98	 */
99	export function useDeviceMode(): DeviceMode {
100	  const [mode, setMode] = React.useState<DeviceMode>(() => readDeviceMode());
101	
102	  React.useLayoutEffect(() => {
103	    let debounceId: ReturnType<typeof setTimeout> | undefined;
104	
105	    const scheduleUpdate = () => {
106	      if (debounceId !== undefined) clearTimeout(debounceId);
107	      debounceId = setTimeout(() => {
108	        debounceId = undefined;
109	        setMode((prev) => {
110	          const next = readDeviceMode(prev);
111	          return prev === next ? prev : next;
112	        });
113	      }, 150);
114	    };
115	
116	    // Leitura inicial imediata (sem debounce), mas ainda com guarda de igualdade.
117	    setMode((prev) => {
118	      const next = readDeviceMode(prev);
119	      return prev === next ? prev : next;
120	    });
121	
122	    const queries = [
123	      window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`),
124	      window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`),
125	      window.matchMedia('(min-aspect-ratio: 11/10)'),
126	      window.matchMedia('(max-aspect-ratio: 10/11)'),
127	    ];
128	    queries.forEach((mq) => mq.addEventListener('change', scheduleUpdate));
129	    window.addEventListener('resize', scheduleUpdate);
130	    window.addEventListener('orientationchange', scheduleUpdate);
131	
132	    return () => {
133	      if (debounceId !== undefined) clearTimeout(debounceId);
134	      queries.forEach((mq) => mq.removeEventListener('change', scheduleUpdate));
135	      window.removeEventListener('resize', scheduleUpdate);
136	      window.removeEventListener('orientationchange', scheduleUpdate);
137	    };
138	  }, []);
139	
140	  return mode;
141	}
142	
143	/**
144	 * `true` quando o dispositivo deve usar layout mobile-essence.
145	 *
146	 * Filosofia: "essência mobile continua + adapta layout pra landscape". Por isso
147	 * inclui qualquer viewport não-desktop:
148	 *  - phones (&lt; 768px)
149	 *  - tablets em portrait (768-1279px, ratio ≤ 10/11)
150	 *  - **tablets em landscape** (768-1279px, ratio ≥ 11/10) — neste caso o
151	 *    JSX mobile é renderizado, mas com classes `tablet:` do Tailwind aplicadas
152	 *    para re-arranjar o layout para landscape (grids mais largos, side panels,
153	 *    typography maior). Use {@link useIsTablet} para diferenciar.
154	 *
155	 * Equivale a `useDeviceMode() !== 'desktop'`.
156	 */
157	export function useIsMobile(): boolean {
158	  return useDeviceMode() !== 'desktop';
159	}
160	
161	/**
162	 * `true` quando o dispositivo está na faixa tablet em landscape
163	 * (768-1279px e aspect-ratio ≥ 11/10, fora da zona morta de histerese).
164	 */
165	export function useIsTablet(): boolean {
166	  return useDeviceMode() === 'tablet';
167	}
168	
169	/**
170	 * Detecta se o dispositivo possui câmera disponível.
171	 *
172	 * Em dispositivos mobile, assume presença de câmera por compatibilidade.
173	 * Em desktop, enumera os media devices para verificar.
174	 */
175	export function useHasCamera(): { hasCamera: boolean; isChecking: boolean } {
176	  const [hasCamera, setHasCamera] = React.useState(false);
177	  const [isChecking, setIsChecking] = React.useState(true);
178	
179	  React.useEffect(() => {
180	    const checkCamera = async () => {
181	      try {
182	        const userAgent = navigator.userAgent.toLowerCase();
183	        const isMobileDevice =
184	          /android|iphone|ipad|ipod|blackberry|windows phone/.test(userAgent);
185	
186	        if (isMobileDevice) {
187	          setHasCamera(true);
188	          setIsChecking(false);
189	          return;
190	        }
191	
192	        if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
193	          setHasCamera(false);
194	          setIsChecking(false);
195	          return;
196	        }
197	
198	        const devices = await navigator.mediaDevices.enumerateDevices();
199	        const videoDevices = devices.filter(
200	          (device) => device.kind === 'videoinput',
201	        );
202	        setHasCamera(videoDevices.length > 0);
203	      } catch (error) {
204	        wideWarn('device.camera_check_error', 'Erro ao verificar câmera', {
205	          attributes: {
206	            'error.message':
207	              error instanceof Error ? error.message : String(error),
208	            'device.has_media_devices': !!navigator.mediaDevices,
209	          },
210	        });
211	        const userAgent = navigator.userAgent.toLowerCase();
212	        const isMobileDevice =
213	          /android|iphone|ipad|ipod|blackberry|windows phone/.test(userAgent);
214	        setHasCamera(isMobileDevice);
215	      } finally {
216	        setIsChecking(false);
217	      }
218	    };
219	
220	    checkCamera();
221	  }, []);
222	
223	  return { hasCamera, isChecking };
224	}
