import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { printHTML } from '@/shared/lib/print';
import { supabase } from '@/integrations/supabase/client';
import { useIsMobile } from '@/shared/hooks/use-mobile';
import { Button } from '@/shared/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/shared/ui/tabs';
import { Card, CardContent } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import {
  ArrowLeft,
  Calendar,
  MapPin,
  DollarSign,
  Leaf,
  Package,
  User,
  Phone,
  FileText,
  CreditCard,
  Printer,
  Info,
} from 'lucide-react';
import { cn } from '@/shared/lib/utils';
import { toast } from '@/shared/hooks/use-toast';
import { wideInfo, wideError } from '@/shared/lib/telemetry/wide-events';
import { enrichWideEvent } from '@/shared/lib/telemetry/enrichWideEvent';
import { handleError } from '@/shared/lib/error-handler';
import { withTrace } from '@/shared/lib/telemetry/tracer';
import { recordOperation, recordOperationDuration, recordError } from '@/shared/lib/telemetry/metrics';
import { useTelemetryAttrs } from '@/shared/lib/telemetry/useTelemetryAttrs';
import { ScrollArea } from '@/shared/ui/scroll-area';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import { Input } from '@/shared/ui/input';
import { useChangelog } from '@/features/eventos/model/useChangelog';
import { ChangelogViewer } from '@/features/eventos/ui/ChangelogViewer';
import { TrendingUp } from 'lucide-react';

// Evita shift de fuso: colunas `date` (YYYY-MM-DD) não devem passar por
// new Date(string) — o JS interpreta como UTC meia-noite e recua 1 dia em UTC-3.
function parseISODateLocal(iso: string) {
  if (!iso) return new Date();
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, (m || 1) - 1, d || 1);
}

// Interface for EncomendaPJ
interface EncomendaPJ {
  id: string;
  cliente_nome: string;
  data_entrega: string;
  hora_entrega: string | null;
  status: 'aberto' | 'pronto' | 'finalizado';
  pedido_descricao: string;
  observacao: string | null;
  lancado_por: string | null;
  cliente_telefone: string | null;
  cliente_endereco: string | null;
  created_at: string;
  valor_total?: number;
  forma_pagamento?: string;
  loja_id?: string;
}

export default function PJDashboard() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const isMobile = useIsMobile();
  const [encomenda, setEncomenda] = useState<EncomendaPJ | null>(null);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState('overview');
  const {
    logs,
    loading: loadingLogs,
    addLog,
    fetchLogs,
  } = useChangelog(id || '', 'ENCOMENDA');
  const telemetryAttrs = useTelemetryAttrs();

  useEffect(() => {
    if (id) {
      fetchEncomenda(id);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  const fetchEncomenda = async (itemId: string) => {
    setLoading(true);
    try {
      await withTrace('eventos.encomenda.carregar', async () => {
        const startTime = performance.now();
        const { data, error } = await supabase
          .from('encomendas')
          .select('*')
          .eq('id', itemId)
          .single();

        if (error) throw error;
        setEncomenda(data);
        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('eventos.encomenda.carregada', 'Encomenda PJ carregada com sucesso', enrichWideEvent('eventos', {
          'encomenda.id': itemId,
          'encomenda.cliente': data?.cliente_nome ?? '',
          'encomenda.status': data?.status ?? '',
          duration_ms: durationMs,
        }));
        recordOperation('eventos.encomenda');
        recordOperationDuration('eventos.encomenda', durationMs);
      }, telemetryAttrs);
    } catch (error: any) {
      wideError('eventos.encomenda.erro', 'Erro ao carregar encomenda PJ', enrichWideEvent('eventos', {
        'encomenda.id': itemId,
        'error.message': error?.message ?? String(error),
        'encomenda.status': '',
      }));
      recordError('eventos_encomenda', 'carregar');
      handleError(error, { domain: 'eventos', operation: 'carregarEncomenda', showToast: false });
      toast({
        title: 'Erro ao carregar encomenda',
        description: error.message,
        variant: 'destructive',
      });
      navigate('/eventos');
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (newStatus: string) => {
    if (!encomenda) return;
    try {
      await withTrace('eventos.encomenda.status', async () => {
        const startTime = performance.now();
        const { error } = await supabase
          .from('encomendas')
          .update({ status: newStatus })
          .eq('id', encomenda.id);

        if (error) throw error;
        setEncomenda({ ...encomenda, status: newStatus as any });
        await addLog(
          'STATUS_CHANGE',
          `Status alterado de ${encomenda.status} para ${newStatus}`,
        );
        const durationMs = Math.round(performance.now() - startTime);
        wideInfo('eventos.encomenda.status_alterado', 'Status da encomenda PJ alterado', enrichWideEvent('eventos', {
          'encomenda.id': encomenda.id,
          'encomenda.cliente': encomenda.cliente_nome,
          'encomenda.status': newStatus,
          'evento.status_anterior': encomenda.status,
          duration_ms: durationMs,
        }));
        recordOperation('eventos.encomenda.status');
        recordOperationDuration('eventos.encomenda.status', durationMs);
      }, telemetryAttrs);
      toast({ title: `Status atualizado para ${newStatus}` });
    } catch (error: any) {
      wideError('eventos.encomenda.status_erro', 'Erro ao alterar status da encomenda PJ', enrichWideEvent('eventos', {
        'encomenda.id': encomenda.id,
        'encomenda.cliente': encomenda.cliente_nome,
        'encomenda.status': newStatus,
        'error.message': error?.message ?? String(error),
      }));
      recordError('eventos_encomenda', 'alterar_status');
      handleError(error, { domain: 'eventos', operation: 'alterarStatusEncomenda', showToast: false });
      toast({
        title: 'Erro ao atualizar status',
        description: error.message,
        variant: 'destructive',
      });
    }
  };

  const handlePrintOS = () => {
    if (!encomenda) return;
    const logoUrl = '/logo sistema/01. Reduzida 5.png';
    {

      const __pjHTML = `
                <html>
                <head>
                    <title>O.S. - ${encomenda.cliente_nome}</title>
                    <style>
                        body { font-family: 'Inter', sans-serif; padding: 40px; color: #333; max-width: 800px; margin: 0 auto; }
                        .header { display: flex; justify-content: space-between; align-items: start; margin-bottom: 40px; border-bottom: 2px solid #C5A065; padding-bottom: 20px; }
                        .logo { height: 80px; }
                        .os-title { text-align: right; color: #2D362E; }
                        .os-title h1 { margin: 0; font-size: 24px; text-transform: uppercase; letter-spacing: 2px; }
                        .os-title p { margin: 5px 0 0; color: #666; font-size: 14px; }
                        .grid { display: grid; grid-template-columns: 1fr 1fr; gap: 30px; margin-bottom: 30px; }
                        .section { margin-bottom: 30px; }
                        .label { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #888; margin-bottom: 5px; font-weight: bold; }
                        .value { font-size: 16px; font-weight: 500; border-bottom: 1px solid #eee; padding-bottom: 5px; }
                        .box { background: #f9f9f9; padding: 20px; border-radius: 8px; border: 1px solid #eee; }
                        .description { white-space: pre-wrap; line-height: 1.6; }
                        .total-box { margin-top: 40px; text-align: right; padding-top: 20px; border-top: 2px solid #C5A065; }
                        .total-label { font-size: 14px; text-transform: uppercase; letter-spacing: 1px; color: #666; }
                        .total-value { font-size: 32px; font-weight: bold; color: #2D362E; margin-top: 5px; }
                        @media print {
                            body { -webkit-print-color-adjust: exact; }
                            .no-print { display: none; }
                        }
                    </style>
                </head>
                <body>
                    <div class="header">
                        <img src="${logoUrl}" class="logo" alt="Momma" onerror="this.style.display='none'">
                        <div class="os-title">
                            <h1>Ordem de Serviço</h1>
                            <p>#${encomenda.id.slice(0, 8)}</p>
                            <p>${new Date().toLocaleDateString()}</p>
                        </div>
                    </div>

                    <div class="grid">
                        <div class="section">
                            <div class="label">Cliente</div>
                            <div class="value">${encomenda.cliente_nome}</div>
                        </div>
                        <div class="section">
                            <div class="label">Contato</div>
                            <div class="value">${encomenda.cliente_telefone || 'Não informado'}</div>
                        </div>
                    </div>

                    <div class="section">
                        <div class="label">Endereço de Entrega</div>
                        <div class="value">${encomenda.cliente_endereco || 'Retirada na loja'}</div>
                    </div>

                    <div class="grid">
                        <div class="section">
                            <div class="label">Data de Entrega</div>
                            <div class="value">${parseISODateLocal(encomenda.data_entrega).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' })}</div>
                        </div>
                        <div class="section">
                            <div class="label">Horário</div>
                            <div class="value">${encomenda.hora_entrega || 'A combinar'}</div>
                        </div>
                    </div>

                    <div class="section">
                        <div class="label">Descrição do Pedido</div>
                        <div class="box description">${encomenda.pedido_descricao}</div>
                    </div>

                    ${
                      encomenda.observacao
                        ? `
                    <div class="section">
                        <div class="label">Observações</div>
                        <div class="box description" style="background: #fff8eb; border-color: #fcebc4;">${encomenda.observacao}</div>
                    </div>
                    `
                        : ''
                    }

                    <div class="total-box">
                        <div class="total-label">Valor Total</div>
                        <div class="total-value">R$ ${encomenda.valor_total?.toLocaleString('pt-BR', { minimumFractionDigits: 2 }) || '0,00'}</div>
                    </div>

                </body>
                </html>
            `;
      printHTML(__pjHTML, { title: `OS - ${encomenda.cliente_nome || ''}` });
    }
  };

  if (loading)
    return (
      <div className="flex items-center justify-center h-screen bg-[#F5F5F0] dark:bg-[#0A0A0A]">
        Carregando...
      </div>
    );
  if (!encomenda)
    return (
      <div className="flex items-center justify-center h-screen bg-[#F5F5F0] dark:bg-[#0A0A0A]">
        Encomenda não encontrada
      </div>
    );

  return (
    <div className="flex flex-col h-[100dvh] bg-white dark:bg-[#0A0A0A] overflow-hidden relative font-sans">
      {/* Store Awning Stripe Effect (Top Border) */}
      <div className="absolute top-0 left-0 right-0 h-1.5 bg-[repeating-linear-gradient(90deg,#C5A065,#C5A065_20px,#ffffff_20px,#ffffff_40px)] opacity-80 z-50" />

      {/* Background Elements */}
      <div
        className="absolute top-[-5%] right-[-10%] w-[300px] h-[300px] opacity-[0.03] dark:opacity-[0.05] pointer-events-none animate-pulse"
        style={{ animationDuration: '10s' }}
      >
        <Leaf className="w-full h-full text-[#C5A065] rotate-12" />
      </div>

      {/* Header */}
      <div className="relative z-20 px-6 pt-8 pb-4 flex items-center gap-4">
        <Button
          data-mia-action="voltar-eventos"
          variant="ghost"
          size="icon"
          onClick={() => navigate('/eventos')}
          className="rounded-full bg-white/50 dark:bg-white/10 hover:bg-white/80 dark:hover:bg-white/20 backdrop-blur-sm shadow-sm"
        >
          <ArrowLeft className="h-5 w-5 text-[#C5A065] dark:text-[#E6DCCF]" />
        </Button>
        <div className="flex-1 min-w-0">
          <Badge
            variant="outline"
            className="mb-1 text-[10px] border-[#C5A065]/50 text-[#8B4513]"
          >
            ENCOMENDA PJ
          </Badge>
          <h1 className="text-xl font-bold text-[#2D362E] dark:text-white truncate leading-tight">
            {encomenda.cliente_nome}
          </h1>
        </div>
        <Select value={encomenda.status} onValueChange={handleStatusChange}>
          <SelectTrigger data-mia-filter="status_encomenda" className="w-[130px] h-8 text-xs bg-white/80 dark:bg-black/20 border-gray-200 dark:border-white/10">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="aberto">Aberto</SelectItem>
            <SelectItem value="pronto">Pronto</SelectItem>
            <SelectItem value="finalizado">Finalizado</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Main Content */}
      <div className="flex-1 overflow-hidden flex flex-col relative z-10">
        <Tabs
          value={activeTab}
          onValueChange={setActiveTab}
          className="flex-1 flex flex-col"
        >
          <div className="px-6 pb-4">
            <TabsList className="w-full h-10 bg-[#E6DCCF]/40 dark:bg-white/5 p-1 rounded-xl grid grid-cols-3 backdrop-blur-sm">
              <TabsTrigger
                data-mia-action="tab-overview"
                value="overview"
                className="rounded-lg data-[state=active]:bg-white dark:data-[state=active]:bg-[#2A2A2A] data-[state=active]:shadow-sm text-xs font-medium"
              >
                Visão Geral & Itens
              </TabsTrigger>
              <TabsTrigger
                data-mia-action="tab-details"
                value="details"
                className="rounded-lg data-[state=active]:bg-white dark:data-[state=active]:bg-[#2A2A2A] data-[state=active]:shadow-sm text-xs font-medium"
              >
                Financeiro & Detalhes
              </TabsTrigger>
              <TabsTrigger
                data-mia-action="tab-changelog"
                value="changelog"
                className="rounded-lg data-[state=active]:bg-white dark:data-[state=active]:bg-[#2A2A2A] data-[state=active]:shadow-sm text-xs font-medium"
              >
                Histórico
              </TabsTrigger>
            </TabsList>
          </div>

          <ScrollArea className="flex-1">
            <div className="px-6 pb-24">
              <TabsContent
                value="changelog"
                className="space-y-6 mt-0 animate-in fade-in slide-in-from-bottom-4 duration-500 h-full min-h-[400px]"
              >
                <Card className="border-none bg-[#F5F5F0]/50 dark:bg-white/5 backdrop-blur-xl h-full shadow-inner">
                  <div className="p-6 h-full flex flex-col">
                    <h3 className="text-lg font-bold text-[#2D362E] dark:text-white mb-4 flex items-center gap-2">
                      <TrendingUp className="h-5 w-5 text-[#C5A065]" />
                      Histórico de Alterações
                    </h3>
                    <div className="flex-1 min-h-0">
                      <ChangelogViewer logs={logs} loading={loadingLogs} />
                    </div>
                  </div>
                </Card>
              </TabsContent>
              <TabsContent
                value="overview"
                className="space-y-6 mt-0 animate-in fade-in slide-in-from-bottom-4 duration-500"
              >
                {/* Info Cards */}
                <div className="grid grid-cols-2 gap-4">
                  <div className="bg-white/60 dark:bg-black/20 backdrop-blur-xl p-4 rounded-2xl border border-white/50 shadow-sm">
                    <div className="text-xs text-muted-foreground uppercase font-bold mb-1 flex items-center">
                      <Calendar className="w-3 h-3 mr-1" /> Data Entrega
                    </div>
                    <div className="font-semibold text-lg">
                      {parseISODateLocal(encomenda.data_entrega).toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' })}
                    </div>
                    <div className="text-sm text-muted-foreground">
                      {encomenda.hora_entrega || 'Horário livre'}
                    </div>
                  </div>
                  <div className="bg-white/60 dark:bg-black/20 backdrop-blur-xl p-4 rounded-2xl border border-white/50 shadow-sm">
                    <div className="text-xs text-muted-foreground uppercase font-bold mb-1 flex items-center">
                      <DollarSign className="w-3 h-3 mr-1" /> Valor Total
                    </div>
                    <div className="font-semibold text-lg text-[#57715B]">
                      R${' '}
                      {encomenda.valor_total?.toLocaleString('pt-BR', {
                        minimumFractionDigits: 2,
                      }) || '0,00'}
                    </div>
                    <div className="text-sm text-muted-foreground">
                      {encomenda.status === 'finalizado' ? 'Pago' : 'Pendente'}
                    </div>
                  </div>
                </div>

                {/* Pedido e Itens */}
                <Card className="border-none bg-[#fff8eb] dark:bg-[#3d3220]/30 shadow-sm rounded-2xl overflow-hidden">
                  <div className="bg-[#fcebc4]/50 dark:bg-[#5c4b30]/50 px-4 py-2 border-b border-[#ebdcb2] dark:border-[#5c4b30] flex justify-between items-center">
                    <h3 className="font-bold text-[#8B4513] dark:text-[#E6DCCF] text-sm flex items-center">
                      <Package className="w-4 h-4 mr-2" /> Descrição do Pedido /
                      Itens
                    </h3>
                  </div>
                  <CardContent className="p-4">
                    <p className="whitespace-pre-wrap text-sm leading-relaxed text-[#5c4b30] dark:text-[#E6DCCF]/90">
                      {encomenda.pedido_descricao}
                    </p>
                  </CardContent>
                </Card>

                <Button data-mia-action="print-o-s"
                  className="w-full h-12 rounded-xl bg-[#C5A065] hover:bg-[#B08D55] text-white shadow-lg shadow-[#C5A065]/20 font-bold"
                  onClick={handlePrintOS}
                >
                  <Printer className="w-4 h-4 mr-2" />
                  Imprimir Ordem de Serviço
                </Button>
