                <div className="bg-white/60 dark:bg-black/20 backdrop-blur-xl rounded-2xl p-6 border border-white/50 space-y-6">
                  <div>
                    <h3 className="text-sm font-bold text-[#C5A065] uppercase tracking-wider mb-4 flex items-center">
                      <User className="w-4 h-4 mr-2" /> Dados do Cliente
                    </h3>
                    <div className="space-y-4">
                      <div>
                        <label className="text-xs text-muted-foreground block mb-1">
                          Nome / Empresa
                        </label>
                        <div className="font-medium">
                          {encomenda.cliente_nome}
                        </div>
                      </div>
                      <div>
                        <label className="text-xs text-muted-foreground block mb-1">
                          Telefone
                        </label>
                        <div className="flex items-center gap-2">
                          <Phone className="w-3 h-3 text-muted-foreground" />
                          <span>{encomenda.cliente_telefone || '—'}</span>
                        </div>
                      </div>
                      <div>
                        <label className="text-xs text-muted-foreground block mb-1">
                          Endereço de Entrega
                        </label>
                        <div className="flex items-start gap-2">
                          <MapPin className="w-3 h-3 text-muted-foreground mt-1" />
                          <span>{encomenda.cliente_endereco || '—'}</span>
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="w-full h-px bg-gray-200 dark:bg-white/10" />

                  <div>
                    <h3 className="text-sm font-bold text-[#C5A065] uppercase tracking-wider mb-4 flex items-center">
                      <CreditCard className="w-4 h-4 mr-2" /> Financeiro
                    </h3>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <label className="text-xs text-muted-foreground block mb-1">
                          Valor Cobrado
                        </label>
                        <div className="font-medium">
                          R${' '}
                          {encomenda.valor_total?.toLocaleString('pt-BR', {
                            minimumFractionDigits: 2,
