                        </label>
                        <div className="font-medium">
                          {encomenda.forma_pagamento || '—'}
                        </div>
                      </div>
                    </div>
                  </div>

                  <div className="w-full h-px bg-gray-200 dark:bg-white/10" />

                  <div>
                    <h3 className="text-sm font-bold text-[#C5A065] uppercase tracking-wider mb-4 flex items-center">
                      <Info className="w-4 h-4 mr-2" /> Outras Informações
                    </h3>
                    <div>
                      <label className="text-xs text-muted-foreground block mb-1">
                        Observações Internas
                      </label>
                      <div className="bg-gray-50 dark:bg-black/20 p-3 rounded-lg text-sm text-gray-600 dark:text-gray-300 min-h-[60px]">
                        {encomenda.observacao ||
                          'Nenhuma observação registrada.'}
