                    </div>
                  </div>
                </div>
              </TabsContent>
            </div>
          </ScrollArea>
        </Tabs>
      </div>

      {/* Mobile Footer Branding */}
      <div className="absolute bottom-0 left-0 right-0 pt-4 pb-[calc(1rem+env(safe-area-inset-bottom))] flex flex-col items-center justify-center gap-2 z-20 pointer-events-none bg-gradient-to-t from-white dark:from-[#0A0A0A] to-transparent">
        <div className="flex items-center gap-2 opacity-60">
          <span className="text-[10px] font-bold text-[#4A3728] dark:text-[#E6DCCF] uppercase tracking-wider">
            sistema GIDAPE
          </span>
        </div>
      </div>
    </div>
  );
