const groupedByDay = React.useMemo(() => {
  // First expand recurring items
  const expandedItems = expandRecurringItems(items);

  // Apply filters
  const q = searchTerm.trim().toLowerCase();
  const normalize = (v: unknown) =>
    String(v ?? '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '');
  const needle = q ? normalize(q) : '';

  const filteredItems = expandedItems.filter((item) => {
    if (typeFilter !== 'todos' && item.type !== typeFilter) return false;
    if (statusFilter === 'aberto' && !isItemAberto(item)) return false;
    if (
      statusFilter === 'finalizado' &&
      item.status !== 'finalizado' &&
      item.status !== 'concluido'
    )
      return false;

    if (needle) {
      const fields =
        item.type === 'evento'
          ? [
              item.nome,
              item.endereco,
              item.responsavel,
              item.telefone_responsavel,
              item.observacoes,
            ]
          : [
              item.cliente_nome,
              item.cliente_endereco,
              item.cliente_telefone,
              item.pedido_descricao,
              item.observacao,
              item.forma_pagamento,
            ];
      if (!fields.some((f) => normalize(f).includes(needle))) return false;
    }
    return true;
  });

  // Group by day
  const map: Record<string, TimelineItem[]> = {};
  weekDays.forEach((d) => (map[d.dateISO] = []));

