export function useDeviceMode(): DeviceMode {
  const [mode, setMode] = React.useState<DeviceMode>(() => readDeviceMode());

  React.useLayoutEffect(() => {
    let debounceId: ReturnType<typeof setTimeout> | undefined;

    const scheduleUpdate = () => {
      if (debounceId !== undefined) clearTimeout(debounceId);
      debounceId = setTimeout(() => {
        debounceId = undefined;
        setMode((prev) => {
          const next = readDeviceMode(prev);
          return prev === next ? prev : next;
        });
      }, 150);
    };

    // Leitura inicial imediata (sem debounce), mas ainda com guarda de igualdade.
    setMode((prev) => {
      const next = readDeviceMode(prev);
      return prev === next ? prev : next;
    });

    const queries = [
      window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`),
      window.matchMedia(`(min-width: ${TABLET_BREAKPOINT}px)`),
      window.matchMedia('(min-aspect-ratio: 11/10)'),
      window.matchMedia('(max-aspect-ratio: 10/11)'),
    ];
    queries.forEach((mq) => mq.addEventListener('change', scheduleUpdate));
    window.addEventListener('resize', scheduleUpdate);
    window.addEventListener('orientationchange', scheduleUpdate);

    return () => {
      if (debounceId !== undefined) clearTimeout(debounceId);
      queries.forEach((mq) => mq.removeEventListener('change', scheduleUpdate));
      window.removeEventListener('resize', scheduleUpdate);
      window.removeEventListener('orientationchange', scheduleUpdate);
    };
  }, []);

  return mode;
